args.new_text:
def total(prices, discount=0.0, tax=0.0):
    """Sum of prices after a fractional discount and optional tax, rounded to cents."""
    subtotal = sum(prices)
    return round(subtotal * discount * (1 + tax), 2)

def test_discount():
    assert total([10, 10], 0.25) == 15.0

def test_tax_after_discount():
    assert total([10, 10], 0.25, 0.10) == 16.5
